pragma solidity ^0.8.20;

import "../interfaces/IHLPMMPool.sol";
import "../interfaces/IERC20.sol";
import "../interfaces/IFeeCollector.sol";
import "../interfaces/IEventEmitter.sol";
import "../interfaces/IMarketNFT.sol";
import "../libraries/PoolMath.sol";
import "../libraries/FeeCalculator.sol";
import "../libraries/TransferHelper.sol";

contract HLPMMPool is IHLPMMPool {
    error Unauthorized();
    error InvalidToken();
    error InsufficientOutput();
    error ReentrancyGuard();
    error ZeroAmount();

    address public immutable token;
    address public immutable usid;
    address public immutable factory;
    address public immutable feeCollector;
    address public immutable eventEmitter;
    address public immutable marketNFT;
    uint256 public immutable nftId;
    uint32 public immutable createdAt;

    uint256 public reserveUSID;
    uint256 public reserveToken;
    uint256 public kLast;
    uint256 public cumulativeFees;

    uint256 private _lastPrice;
    uint256 private _priceAccumulator;
    uint32 private _lastPriceUpdate;

    uint256 private _unlocked = 1;

    modifier lock() {
        if (_unlocked != 1) revert ReentrancyGuard();
        _unlocked = 2;
        _;
        _unlocked = 1;
    }

    modifier onlyMarketNFT() {
        if (msg.sender != marketNFT) revert Unauthorized();
        _;
    }

    constructor(
        address token_,
        address usid_,
        address factory_,
        address feeCollector_,
        address eventEmitter_,
        address marketNFT_,
        uint256 nftId_
    ) {
        token = token_;
        usid = usid_;
        factory = factory_;
        feeCollector = feeCollector_;
        eventEmitter = eventEmitter_;
        marketNFT = marketNFT_;
        nftId = nftId_;
        createdAt = uint32(block.timestamp);
    }

    function initialize(uint256 usidAmount, uint256 tokenAmount) external {
        if (msg.sender != factory) revert Unauthorized();

        reserveUSID = usidAmount;
        reserveToken = tokenAmount;
        kLast = usidAmount * tokenAmount;

        _lastPrice = PoolMath.getSpotPrice(usidAmount, tokenAmount);
        _lastPriceUpdate = uint32(block.timestamp);

        emit Sync(usidAmount, tokenAmount);
    }

    function getReserves() external view returns (uint256 _reserveUSID, uint256 _reserveToken) {
        _reserveUSID = reserveUSID;
        _reserveToken = reserveToken;
    }

    function swap(
        address tokenIn,
        uint256 amountIn,
        uint256 amountOutMin,
        address to
    ) external lock returns (uint256 amountOut) {
        if (amountIn == 0) revert ZeroAmount();
        if (tokenIn != token && tokenIn != usid) revert InvalidToken();

        bool isUSIDIn = tokenIn == usid;

        uint256 reserveIn = isUSIDIn ? reserveUSID : reserveToken;
        uint256 reserveOut = isUSIDIn ? reserveToken : reserveUSID;

        uint32 poolAge = uint32(block.timestamp) - createdAt;
        uint256 volatility = _calculateVolatility();
        uint256 concentration = _getTopHolderConcentration();

        (uint256 feeAmount, ) = FeeCalculator.calculateFee(
            amountIn,
            poolAge,
            volatility,
            concentration
        );

        uint256 amountInAfterFee = amountIn - feeAmount;
        amountOut = PoolMath.getAmountOut(amountInAfterFee, reserveIn, reserveOut);

        if (amountOut < amountOutMin) revert InsufficientOutput();

        if (isUSIDIn) {
            reserveUSID = reserveUSID + amountIn;
            reserveToken = reserveToken - amountOut;
        } else {
            reserveToken = reserveToken + amountIn;
            reserveUSID = reserveUSID - amountOut;
        }

        kLast = reserveUSID * reserveToken;

        if (feeAmount > 0) {
            cumulativeFees += feeAmount;
            if (isUSIDIn) {
                TransferHelper.safeTransfer(usid, feeCollector, feeAmount);
            } else {
                uint256 usidFee = PoolMath.getAmountOut(feeAmount, reserveToken, reserveUSID);
                reserveToken += feeAmount;
                reserveUSID -= usidFee;
                TransferHelper.safeTransfer(usid, feeCollector, usidFee);
                feeAmount = usidFee;
            }
            IFeeCollector(feeCollector).accumulateFee(nftId, feeAmount);
        }

        address tokenOut = isUSIDIn ? token : usid;
        TransferHelper.safeTransfer(tokenOut, to, amountOut);

        _updatePrice();

        IEventEmitter(eventEmitter).emitSwap(
            address(this),
            msg.sender,
            tokenIn,
            tokenOut,
            amountIn,
            amountOut,
            reserveUSID,
            reserveToken,
            feeAmount
        );

        emit Sync(reserveUSID, reserveToken);
    }

    function claimFees(address /* recipient */) external onlyMarketNFT returns (uint256 amount) {
        amount = cumulativeFees;
        if (amount > 0) {
            cumulativeFees = 0;
        }
    }

    function sync() external {
        uint256 usidBalance = IERC20(usid).balanceOf(address(this));
        uint256 tokenBalance = IERC20(token).balanceOf(address(this));

        reserveUSID = usidBalance;
        reserveToken = tokenBalance;
        kLast = usidBalance * tokenBalance;

        emit Sync(usidBalance, tokenBalance);
    }

    function _updatePrice() internal {
        uint256 currentPrice = PoolMath.getSpotPrice(reserveUSID, reserveToken);
        uint32 timeElapsed = uint32(block.timestamp) - _lastPriceUpdate;

        if (timeElapsed > 0) {
            _priceAccumulator += (_lastPrice * timeElapsed);
            _lastPrice = currentPrice;
            _lastPriceUpdate = uint32(block.timestamp);
        }
    }

    function _calculateVolatility() internal view returns (uint256) {
        uint256 currentPrice = PoolMath.getSpotPrice(reserveUSID, reserveToken);
        if (_lastPrice == 0) return 0;

        uint256 priceDiff = currentPrice > _lastPrice 
            ? currentPrice - _lastPrice 
            : _lastPrice - currentPrice;

        return (priceDiff * 10000) / _lastPrice;
    }

    function _getTopHolderConcentration() internal view returns (uint256) {
        uint256 totalSupply = IERC20(token).totalSupply();
        if (totalSupply == 0) return 0;

        uint256 poolBalance = IERC20(token).balanceOf(address(this));
        uint256 circulatingSupply = totalSupply - poolBalance;

        if (circulatingSupply == 0) return 0;

        return 500;
    }

    function getSpotPrice() external view returns (uint256) {
        return PoolMath.getSpotPrice(reserveUSID, reserveToken);
    }

    function getMarketCap() external view returns (uint256) {
        uint256 totalSupply = IERC20(token).totalSupply();
        return PoolMath.getMarketCap(reserveUSID, reserveToken, totalSupply);
   }
}


