pragma solidity ^0.8.20;

import "./IMarketNFT.sol";

interface IEventEmitter {
    event MarketCreated(
        address indexed pool,
        address indexed token,
        uint256 indexed nftId,
        address creator,
        string name,
        string symbol,
        uint256 timestamp
    );

    event Swap(
        address indexed pool,
        address indexed sender,
        address tokenIn,
        address tokenOut,
        uint256 amountIn,
        uint256 amountOut,
        uint256 newReserveUSID,
        uint256 newReserveToken,
        uint256 feeAmount,
        uint256 timestamp
    );

    event FeeClaimed(
        address indexed pool,
        uint256 indexed nftId,
        address indexed recipient,
        uint256 amount,
        uint256 timestamp
    );

    event FeeStrategyUpdated(
        uint256 indexed nftId,
        FeeStrategy newStrategy,
        uint256 timestamp
    );

    function factory() external view returns (address);
    function isAuthorizedEmitter(address emitter) external view returns (bool);

    function authorizeEmitter(address emitter) external;
    function revokeEmitter(address emitter) external;
    function adminAuthorizeEmitter(address emitter) external;
    function adminRevokeEmitter(address emitter) external;

    function emitMarketCreated(
        address pool,
        address token,
        uint256 nftId,
        address creator,
        string memory name,
        string memory symbol
    ) external;

    function emitSwap(
        address pool,
        address sender,
        address tokenIn,
        address tokenOut,
        uint256 amountIn,
        uint256 amountOut,
        uint256 newReserveUSID,
        uint256 newReserveToken,
        uint256 feeAmount
    ) external;

    function emitFeeClaimed(
        address pool,
        uint256 nftId,
        address recipient,
        uint256 amount
    ) external;

    function emitFeeStrategyUpdated(
        uint256 nftId,
        FeeStrategy newStrategy
    ) external;
}

