pragma solidity ^0.8.20;

import "../interfaces/IFeeCollector.sol";
import "../interfaces/IUSID.sol";
import "../interfaces/IMarketNFT.sol";
import "../interfaces/IHLPMMPool.sol";
import "../interfaces/IEventEmitter.sol";
import "../libraries/TransferHelper.sol";

contract FeeCollector is IFeeCollector {
    error Unauthorized();
    error FactoryAlreadySet();
    error NoFeesToClaim();
    error InvalidNFT();

    address public factory;
    address public usid;
    address public marketNFT;
    address public eventEmitter;
    address private immutable _deployer;

    mapping(uint256 => uint256) public accumulatedFees;
    mapping(uint256 => uint256) public airdropPool;

    modifier onlyAuthorized() {
        if (msg.sender != factory && msg.sender != marketNFT) revert Unauthorized();
        _;
    }

    modifier onlyPool() {
        if (msg.sender == address(0)) revert Unauthorized();
        _;
    }

    constructor(address usid_) {
        _deployer = msg.sender;
        usid = usid_;
    }

    function setFactory(address factory_, address marketNFT_, address eventEmitter_) external {
        if (msg.sender != _deployer) revert Unauthorized();
        if (factory != address(0)) revert FactoryAlreadySet();
        factory = factory_;
        marketNFT = marketNFT_;
        eventEmitter = eventEmitter_;
    }

    function accumulateFee(uint256 nftId, uint256 amount) external onlyPool {
        if (amount == 0) return;

        accumulatedFees[nftId] += amount;
        emit FeeAccumulated(nftId, amount);
    }

    function distributeFees(
        uint256 nftId,
        address recipient,
        FeeStrategy strategy
    ) external returns (uint256 amount) {
        if (msg.sender != marketNFT) revert Unauthorized();

        amount = accumulatedFees[nftId];
        if (amount == 0) revert NoFeesToClaim();

        accumulatedFees[nftId] = 0;

        address pool = IMarketNFT(marketNFT).nftToPool(nftId);

        if (strategy == FeeStrategy.CLAIM) {
            TransferHelper.safeTransfer(usid, recipient, amount);
        } else if (strategy == FeeStrategy.BURN) {
            IUSID(usid).burn(address(this), amount);
        } else if (strategy == FeeStrategy.AIRDROP) {
            airdropPool[nftId] += amount;
        } else if (strategy == FeeStrategy.LP_REWARDS) {
            TransferHelper.safeTransfer(usid, pool, amount);
            IHLPMMPool(pool).sync();
        }

        IEventEmitter(eventEmitter).emitFeeClaimed(pool, nftId, recipient, amount);
        emit FeeDistributed(nftId, recipient, amount, strategy);
    }

    function pendingFees(uint256 nftId) external view returns (uint256) {
        return accumulatedFees[nftId];
    }

    function claimAirdrop(uint256 nftId, address[] calldata recipients, uint256[] calldata amounts) external {
        address owner = IMarketNFT(marketNFT).ownerOf(nftId);
        if (msg.sender != owner) revert Unauthorized();
        if (recipients.length != amounts.length) revert Unauthorized();

        uint256 total = 0;
        for (uint256 i = 0; i < amounts.length; i++) {
            total += amounts[i];
        }

        if (total > airdropPool[nftId]) revert Unauthorized();
        airdropPool[nftId] -= total;

        for (uint256 i = 0; i < recipients.length; i++) {
            TransferHelper.safeTransfer(usid, recipients[i], amounts[i]);
        }
    }

    function setEventEmitter(address eventEmitter_) external {
        if (msg.sender != _deployer) revert Unauthorized();
        eventEmitter = eventEmitter_;
    }

    function setMarketNFT(address marketNFT_) external {
        if (msg.sender != _deployer) revert Unauthorized();
        marketNFT = marketNFT_;
    }
}


