pragma solidity ^0.8.20;

import "../interfaces/IHLPMMQuoter.sol";
import "../interfaces/IHLPMMFactory.sol";
import "../interfaces/IHLPMMPool.sol";
import "../interfaces/IERC20.sol";
import "../libraries/PoolMath.sol";
import "../libraries/FeeCalculator.sol";

contract HLPMMQuoter is IHLPMMQuoter {
    error InvalidPath();
    error PoolNotFound();

    address public immutable factory;
    address public immutable usid;

    constructor(address factory_, address usid_) {
        factory = factory_;
        usid = usid_;
    }

    function quoteExactInput(
        address tokenIn,
        address tokenOut,
        uint256 amountIn
    ) external view returns (uint256 amountOut) {
        address pool = _getPool(tokenIn, tokenOut);

        (uint256 reserveUSID, uint256 reserveToken) = IHLPMMPool(pool).getReserves();
        // Pool token resolved via reserves

        bool isUSIDIn = tokenIn == usid;
        uint256 reserveIn = isUSIDIn ? reserveUSID : reserveToken;
        uint256 reserveOut = isUSIDIn ? reserveToken : reserveUSID;

        uint32 poolAge = uint32(block.timestamp) - IHLPMMPool(pool).createdAt();
        uint256 feeBps = FeeCalculator.getEffectiveFee(poolAge, 0, 500);

        (amountOut, ) = PoolMath.getAmountOutWithFee(amountIn, reserveIn, reserveOut, feeBps);
    }

    function quoteExactInputMultiHop(
        address[] calldata path,
        uint256 amountIn
    ) external view returns (uint256 amountOut) {
        if (path.length < 2) revert InvalidPath();

        amountOut = amountIn;

        for (uint256 i = 0; i < path.length - 1; i++) {
            address tokenIn = path[i];
            address tokenOut = path[i + 1];

            address pool = _getPool(tokenIn, tokenOut);

            (uint256 reserveUSID, uint256 reserveToken) = IHLPMMPool(pool).getReserves();

            bool isUSIDIn = tokenIn == usid;
            uint256 reserveIn = isUSIDIn ? reserveUSID : reserveToken;
            uint256 reserveOut = isUSIDIn ? reserveToken : reserveUSID;

            uint32 poolAge = uint32(block.timestamp) - IHLPMMPool(pool).createdAt();
            uint256 feeBps = FeeCalculator.getEffectiveFee(poolAge, 0, 500);

            (amountOut, ) = PoolMath.getAmountOutWithFee(amountOut, reserveIn, reserveOut, feeBps);
        }
    }

    function quoteExactOutput(
        address tokenIn,
        address tokenOut,
        uint256 amountOut
    ) external view returns (uint256 amountIn) {
        address pool = _getPool(tokenIn, tokenOut);

        (uint256 reserveUSID, uint256 reserveToken) = IHLPMMPool(pool).getReserves();

        bool isUSIDIn = tokenIn == usid;
        uint256 reserveIn = isUSIDIn ? reserveUSID : reserveToken;
        uint256 reserveOut = isUSIDIn ? reserveToken : reserveUSID;

        uint32 poolAge = uint32(block.timestamp) - IHLPMMPool(pool).createdAt();
        uint256 feeBps = FeeCalculator.getEffectiveFee(poolAge, 0, 500);

        (amountIn, ) = PoolMath.getAmountInWithFee(amountOut, reserveIn, reserveOut, feeBps);
    }

    function getPriceImpact(
        address pool,
        uint256 amountIn,
        bool isUSIDIn
    ) external view returns (uint256 impactBps) {
        (uint256 reserveUSID, uint256 reserveToken) = IHLPMMPool(pool).getReserves();

        uint256 reserveIn = isUSIDIn ? reserveUSID : reserveToken;

        impactBps = PoolMath.calculatePriceImpact(amountIn, reserveIn);
    }

    function getSpotPrice(address pool) external view returns (uint256 price) {
        (uint256 reserveUSID, uint256 reserveToken) = IHLPMMPool(pool).getReserves();
        price = PoolMath.getSpotPrice(reserveUSID, reserveToken);
    }

    function getMarketCap(address pool) external view returns (uint256 marketCap) {
        (uint256 reserveUSID, uint256 reserveToken) = IHLPMMPool(pool).getReserves();
        address token = IHLPMMPool(pool).token();
        uint256 totalSupply = IERC20(token).totalSupply();

        marketCap = PoolMath.getMarketCap(reserveUSID, reserveToken, totalSupply);
    }

    function getPoolInfo(address pool) external view returns (
        address token,
        uint256 reserveUSID,
        uint256 reserveToken,
        uint256 spotPrice,
        uint256 marketCap,
        uint32 createdAt,
        uint256 nftId
    ) {
        token = IHLPMMPool(pool).token();
        (reserveUSID, reserveToken) = IHLPMMPool(pool).getReserves();
        spotPrice = PoolMath.getSpotPrice(reserveUSID, reserveToken);

        uint256 totalSupply = IERC20(token).totalSupply();
        marketCap = PoolMath.getMarketCap(reserveUSID, reserveToken, totalSupply);

        createdAt = IHLPMMPool(pool).createdAt();
        nftId = IHLPMMPool(pool).nftId();
    }

    function _getPool(address tokenA, address tokenB) internal view returns (address pool) {
        address token = tokenA == usid ? tokenB : tokenA;
        pool = IHLPMMFactory(factory).tokenToPool(token);
        if (pool == address(0)) revert PoolNotFound();
   }
}


