contract MarketNFT is IMarketNFT, IERC721Metadata {
    error Unauthorized();
    error FactoryAlreadySet();
    error InvalidTokenId();
    error NotOwnerOrApproved();
    error TransferToZeroAddress();
    error MintToZeroAddress();
    error TokenAlreadyMinted();
    error ApprovalToCurrentOwner();
    error ApproveCallerNotOwnerNorApproved();
    error TransferFromIncorrectOwner();
    error ERC721InvalidReceiver(address receiver);

    string public constant name = "HLPMM Market Position";
    string public constant symbol = "HLPMM-POS";

    address public factory;
    address public feeCollector;
    address public eventEmitter;
    address private immutable _deployer;

    uint256 public totalMinted;

    mapping(uint256 => address) private _owners;
    mapping(address => uint256) private _balances;
    mapping(uint256 => address) private _tokenApprovals;
    mapping(address => mapping(address => bool)) private _operatorApprovals;

    mapping(uint256 => address) public nftToPool;
    mapping(uint256 => FeeStrategy) public feeStrategy;

    modifier onlyFactory() {
        if (msg.sender != factory) revert Unauthorized();
        _;
    }

    constructor() {
        _deployer = msg.sender;
    }

    function setFactory(address factory_, address feeCollector_, address eventEmitter_) external {
        if (msg.sender != _deployer) revert Unauthorized();
        if (factory != address(0)) revert FactoryAlreadySet();
        factory = factory_;
        feeCollector = feeCollector_;
        eventEmitter = eventEmitter_;
    }

    function mint(address to, address pool, FeeStrategy initialStrategy) external onlyFactory returns (uint256 tokenId) {
        if (to == address(0)) revert MintToZeroAddress();

        tokenId = ++totalMinted;

        _balances[to] += 1;
        _owners[tokenId] = to;
        nftToPool[tokenId] = pool;
        feeStrategy[tokenId] = initialStrategy;

        emit Transfer(address(0), to, tokenId);
        if (initialStrategy != FeeStrategy.CLAIM) {
            IEventEmitter(eventEmitter).emitFeeStrategyUpdated(tokenId, initialStrategy);
            emit FeeStrategyUpdated(tokenId, initialStrategy);
        }
    }

    function setFeeStrategy(uint256 tokenId, FeeStrategy strategy) external {
        if (!_isApprovedOrOwner(msg.sender, tokenId)) revert NotOwnerOrApproved();

        feeStrategy[tokenId] = strategy;

        IEventEmitter(eventEmitter).emitFeeStrategyUpdated(tokenId, strategy);
        emit FeeStrategyUpdated(tokenId, strategy);
    }

    function claimFees(uint256 tokenId) external returns (uint256 amount) {
        if (!_isApprovedOrOwner(msg.sender, tokenId)) revert NotOwnerOrApproved();

        address owner = ownerOf(tokenId);
        FeeStrategy strategy = feeStrategy[tokenId];

        amount = IFeeCollector(feeCollector).distributeFees(tokenId, owner, strategy);

        emit FeesClaimed(tokenId, owner, amount);
    }

    function balanceOf(address owner) external view returns (uint256) {
        return _balances[owner];
    }

    function ownerOf(uint256 tokenId) public view returns (address) {
        address owner = _owners[tokenId];
        if (owner == address(0)) revert InvalidTokenId();
        return owner;
    }

    function tokenURI(uint256 tokenId) external view returns (string memory) {
        if (_owners[tokenId] == address(0)) revert InvalidTokenId();
        return "";
    }

    function approve(address to, uint256 tokenId) external {
        address owner = ownerOf(tokenId);
        if (to == owner) revert ApprovalToCurrentOwner();

        if (msg.sender != owner && !_operatorApprovals[owner][msg.sender]) {
            revert ApproveCallerNotOwnerNorApproved();
        }

        _tokenApprovals[tokenId] = to;
        emit Approval(owner, to, tokenId);
    }

    function setApprovalForAll(address operator, bool approved) external {
        _operatorApprovals[msg.sender][operator] = approved;
        emit ApprovalForAll(msg.sender, operator, approved);
    }

    function getApproved(uint256 tokenId) external view returns (address) {
        if (_owners[tokenId] == address(0)) revert InvalidTokenId();
        return _tokenApprovals[tokenId];
    }

    function isApprovedForAll(address owner, address operator) external view returns (bool) {
        return _operatorApprovals[owner][operator];
    }

    function transferFrom(address from, address to, uint256 tokenId) public {
        if (!_isApprovedOrOwner(msg.sender, tokenId)) revert NotOwnerOrApproved();
        _transfer(from, to, tokenId);
    }

    function safeTransferFrom(address from, address to, uint256 tokenId) external {
        safeTransferFrom(from, to, tokenId, "");
    }

    function safeTransferFrom(address from, address to, uint256 tokenId, bytes memory data) public {
        if (!_isApprovedOrOwner(msg.sender, tokenId)) revert NotOwnerOrApproved();
        _transfer(from, to, tokenId);
        _checkOnERC721Received(from, to, tokenId, data);
    }

    function _transfer(address from, address to, uint256 tokenId) internal {
        if (ownerOf(tokenId) != from) revert TransferFromIncorrectOwner();
        if (to == address(0)) revert TransferToZeroAddress();

        delete _tokenApprovals[tokenId];

        _balances[from] -= 1;
        _balances[to] += 1;
        _owners[tokenId] = to;

        emit Transfer(from, to, tokenId);
    }

    function _isApprovedOrOwner(address spender, uint256 tokenId) internal view returns (bool) {
        address owner = ownerOf(tokenId);
        return (spender == owner || 
                _tokenApprovals[tokenId] == spender || 
                _operatorApprovals[owner][spender]);
    }

    function _checkOnERC721Received(address from, address to, uint256 tokenId, bytes memory data) private {
        if (to.code.length > 0) {
            try IERC721Receiver(to).onERC721Received(msg.sender, from, tokenId, data) returns (bytes4 retval) {
                if (retval != IERC721Receiver.onERC721Received.selector) {
                    revert ERC721InvalidReceiver(to);
                }
            } catch (bytes memory reason) {
                if (reason.length == 0) {
                    revert ERC721InvalidReceiver(to);
                } else {
                    assembly {
                        revert(add(32, reason), mload(reason))
                    }
                }
            }
        }
    }

    function supportsInterface(bytes4 interfaceId) external pure returns (bool) {
        return
            interfaceId == 0x01ffc9a7 || // ERC165
            interfaceId == 0x80ac58cd || // ERC721
            interfaceId == 0x5b5e139f;   // ERC721Metadata
    }

    function setFeeCollector(address feeCollector_) external {
        if (msg.sender != _deployer) revert Unauthorized();
        feeCollector = feeCollector_;
    }

    function setEventEmitter(address eventEmitter_) external {
        if (msg.sender != _deployer) revert Unauthorized();
        eventEmitter = eventEmitter_;
    }
}


