// SPDX-License-Identifier: GPL-3.0
pragma solidity ^0.8.20;

import "../interfaces/IFeeCollectorV2.sol";
import "../interfaces/IEventEmitterV2.sol";
import "../interfaces/IAdminController.sol";
import "../interfaces/IStablecoinRegistry.sol";

interface IERC20Minimal {
    function balanceOf(address) external view returns (uint256);
    function transfer(address to, uint256 amount) external returns (bool);
    function totalSupply() external view returns (uint256);
}

/// @title FeeCollectorV2 - Multi-stable fee accumulation and distribution
/// @notice Accumulates fees from pools in any approved stablecoin.
///         Distributes via 4 strategies: CLAIM, BURN, AIRDROP, LP_REWARDS.
///         Uses AdminController for consistent admin pattern.
contract FeeCollectorV2 is IFeeCollectorV2 {
    error Unauthorized();
    error ZeroAddress();
    error NoFeesToDistribute();

    IAdminController public immutable adminController;
    address public stablecoinRegistry;
    address public factory;
    address public marketNFT;
    address public eventEmitter;

    // nftId => total accumulated fees (USD value, accounting only)
    mapping(uint256 => uint256) private _pendingFees;

    // nftId => stablecoin => amount (actual tokens held)
    mapping(uint256 => mapping(address => uint256)) private _feeBalances;

    // Track which stablecoins have fees for a given nftId
    mapping(uint256 => address[]) private _feeStablecoins;

    modifier onlyAuthorized() {
        // Pools and factory can accumulate fees
        if (msg.sender != factory && msg.sender != marketNFT) {
            // Check if it's a pool by seeing if factory recognizes it
            revert Unauthorized();
        }
        _;
    }

    modifier onlyOperatorOrAbove() {
        if (!adminController.hasRole(msg.sender, IAdminController.Role.ADMIN) &&
            !adminController.hasRole(msg.sender, IAdminController.Role.OPERATOR)) {
            revert Unauthorized();
        }
        _;
    }

    constructor(address adminController_) {
        if (adminController_ == address(0)) revert ZeroAddress();
        adminController = IAdminController(adminController_);
    }

    function setProtocolAddresses(
        address factory_,
        address marketNFT_,
        address eventEmitter_,
        address stablecoinRegistry_
    ) external onlyOperatorOrAbove {
        factory = factory_;
        marketNFT = marketNFT_;
        eventEmitter = eventEmitter_;
        stablecoinRegistry = stablecoinRegistry_;
    }

    /// @notice Accumulate fee from a pool swap
    /// @param nftId The market NFT that owns these fees
    /// @param stablecoin The stablecoin the fee is denominated in (address(0) for token-side fees)
    /// @param amount The fee amount in USD terms
    function accumulateFee(uint256 nftId, address stablecoin, uint256 amount) external {
        // Anyone can call this (pools call it during swap)
        // The actual stablecoins are held by the pool or transferred here
        _pendingFees[nftId] += amount;

        if (stablecoin != address(0)) {
            // Track per-stablecoin balance
            if (_feeBalances[nftId][stablecoin] == 0) {
                _feeStablecoins[nftId].push(stablecoin);
            }
            _feeBalances[nftId][stablecoin] += amount;
        }

        emit FeeAccumulated(nftId, stablecoin, amount);
    }

    /// @notice Distribute accumulated fees according to strategy
    /// @param nftId The market NFT ID
    /// @param recipient The fee recipient (NFT owner)
    /// @param strategy The distribution strategy
    /// @return amount Total USD value distributed
    function distributeFees(
        uint256 nftId,
        address recipient,
        FeeStrategy strategy
    ) external returns (uint256 amount) {
        if (msg.sender != marketNFT) revert Unauthorized();

        amount = _pendingFees[nftId];
        if (amount == 0) revert NoFeesToDistribute();

        _pendingFees[nftId] = 0;

        if (strategy == FeeStrategy.CLAIM) {
            // Send all accumulated stablecoins to recipient
            _sendAllFees(nftId, recipient);
        } else if (strategy == FeeStrategy.BURN) {
            // Burn by sending to dead address
            _sendAllFees(nftId, address(0xdead));
        } else if (strategy == FeeStrategy.AIRDROP) {
            // For AIRDROP: fees stay in collector until a separate airdrop mechanism claims them
            // Just reset the pending counter; balances remain for airdrop distribution
            // (Airdrop logic would be a separate admin-triggered function)
        } else if (strategy == FeeStrategy.LP_REWARDS) {
            // For LP_REWARDS: send back to pool to deepen liquidity
            // TODO: implement pool liquidity injection
        }

        // Emit via EventEmitter
        if (eventEmitter != address(0)) {
            IEventEmitterV2(eventEmitter).emitFeeClaimed(
                address(0), nftId, recipient, amount
            );
        }

        emit FeeDistributed(nftId, recipient, amount, strategy);
    }

    function pendingFees(uint256 nftId) external view returns (uint256) {
        return _pendingFees[nftId];
    }

    // ─── Internal ────────────────────────────────────────────────────────

    function _sendAllFees(uint256 nftId, address to) internal {
        address[] storage stables = _feeStablecoins[nftId];
        for (uint256 i = 0; i < stables.length; i++) {
            uint256 bal = _feeBalances[nftId][stables[i]];
            if (bal > 0) {
                _feeBalances[nftId][stables[i]] = 0;
                uint256 available = IERC20Minimal(stables[i]).balanceOf(address(this));
                if (available >= bal) {
                    IERC20Minimal(stables[i]).transfer(to, bal);
                } else if (available > 0) {
                    IERC20Minimal(stables[i]).transfer(to, available);
                }
            }
        }
        delete _feeStablecoins[nftId];
    }
}

contracts/v2/periphery/HLPMMQuoterV2.sol.content:
// SPDX-License-Identifier: GPL-3.0
pragma solidity ^0.8.20;

import "../interfaces/IHLPMMQuoterV2.sol";
import "../interfaces/IHLPMMFactoryV2.sol";
import "../interfaces/IHLPMMPoolV2.sol";
import "../interfaces/IHLPMMTokenV2.sol";
import "../libraries/PoolMathV2.sol";
import "../libraries/FeeCalculatorV2.sol";

interface IERC20Supply {
    function totalSupply() external view returns (uint256);
}

/// @title HLPMMQuoterV2 - View-only swap simulation and pool introspection
/// @notice Gas-free quote functions for UI integration and algorithmic trading.
///         Aware of virtual reserves and multi-stable pools.
contract HLPMMQuoterV2 is IHLPMMQuoterV2 {
    error PoolNotFound();

    address public immutable factory;

    constructor(address factory_) {
        factory = factory_;
    }

    /// @notice Quote a token-to-token swap (multi-hop through USD)
    /// @param amountIn Input amount
    /// @param tokenIn Source token (could be a stablecoin or market token)
    /// @param tokenOut Destination token
    /// @return amountOut Expected output
    /// @return priceImpact Price impact in basis points
    function quoteExactInput(
        uint256 amountIn,
        address tokenIn,
        address tokenOut
    ) external view returns (uint256 amountOut, uint256 priceImpact) {
        // If tokenIn is a market token, first leg: tokenIn → USD
        address poolIn = IHLPMMFactoryV2(factory).tokenToPool(tokenIn);
        address poolOut = IHLPMMFactoryV2(factory).tokenToPool(tokenOut);

        if (poolIn != address(0) && poolOut != address(0)) {
            // Token → Token (multi-hop): tokenIn → USD → tokenOut
            (uint256 usdAmount, uint256 impact1) = _quoteTokenToUSD(poolIn, amountIn);
            (amountOut, priceImpact) = _quoteUSDToToken(poolOut, usdAmount);
            // Combine price impacts (approximate)
            priceImpact = impact1 + priceImpact;
        } else if (poolIn != address(0)) {
            // Token → Stable
            (amountOut, priceImpact) = _quoteTokenToUSD(poolIn, amountIn);
        } else if (poolOut != address(0)) {
            // Stable → Token
            (amountOut, priceImpact) = _quoteUSDToToken(poolOut, amountIn);
        } else {
            revert PoolNotFound();
        }
    }

    /// @notice Quote a stablecoin-to-token swap
    function quoteStableToToken(
        uint256 amountIn,
        address token
    ) external view returns (uint256 amountOut, uint256 priceImpact) {
        address pool = IHLPMMFactoryV2(factory).tokenToPool(token);
        if (pool == address(0)) revert PoolNotFound();
        (amountOut, priceImpact) = _quoteUSDToToken(pool, amountIn);
    }

    /// @notice Quote a token-to-stablecoin swap
    function quoteTokenToStable(
        uint256 amountIn,
        address token
    ) external view returns (uint256 amountOut, uint256 priceImpact) {
        address pool = IHLPMMFactoryV2(factory).tokenToPool(token);
        if (pool == address(0)) revert PoolNotFound();
        (amountOut, priceImpact) = _quoteTokenToUSD(pool, amountIn);
    }

    /// @notice Get comprehensive pool information
    function getPoolInfo(address token) external view returns (PoolInfo memory info) {
        address pool = IHLPMMFactoryV2(factory).tokenToPool(token);
        if (pool == address(0)) revert PoolNotFound();

        IHLPMMPoolV2 p = IHLPMMPoolV2(pool);

        info.virtualReserveUSD = p.virtualReserveUSD();
        info.realReserveUSD = p.realReserveUSD();
        info.effectiveReserveUSD = p.getEffectiveReserveUSD();
        info.reserveToken = p.reserveToken();
        info.spotPrice = p.getSpotPrice();
        info.marketCap = p.getMarketCap();
        info.volatility = p.getVolatility();
        info.poolAge = uint32(block.timestamp) - p.createdAt();
    }

    // ─── Internal quote helpers ──────────────────────────────────────────

    function _quoteUSDToToken(
        address pool,
        uint256 usdAmountIn
    ) internal view returns (uint256 amountOut, uint256 priceImpact) {
        IHLPMMPoolV2 p = IHLPMMPoolV2(pool);

        uint256 effectiveUSD = p.getEffectiveReserveUSD();
        uint256 tokenReserve = p.reserveToken();

        // Calculate fee
        uint32 poolAge = uint32(block.timestamp) - p.createdAt();
        uint256 volatility = p.getVolatility();

        (uint256 feeAmount, ) = FeeCalculatorV2.calculateFee(
            usdAmountIn, poolAge, volatility, 500 // approximate concentration for quote
        );

        uint256 amountInAfterFee = usdAmountIn - feeAmount;
        amountOut = PoolMathV2.getAmountOut(amountInAfterFee, effectiveUSD, tokenReserve);
        priceImpact = PoolMathV2.calculatePriceImpact(amountInAfterFee, effectiveUSD);
    }

    function _quoteTokenToUSD(
        address pool,
        uint256 tokenAmountIn
    ) internal view returns (uint256 amountOut, uint256 priceImpact) {
        IHLPMMPoolV2 p = IHLPMMPoolV2(pool);

        uint256 effectiveUSD = p.getEffectiveReserveUSD();
        uint256 tokenReserve = p.reserveToken();

        // Calculate fee
        uint32 poolAge = uint32(block.timestamp) - p.createdAt();
        uint256 volatility = p.getVolatility();

        (uint256 feeAmount, ) = FeeCalculatorV2.calculateFee(
            tokenAmountIn, poolAge, volatility, 500
        );

        uint256 amountInAfterFee = tokenAmountIn - feeAmount;
        amountOut = PoolMathV2.getAmountOut(amountInAfterFee, tokenReserve, effectiveUSD);
        priceImpact = PoolMathV2.calculatePriceImpact(amountInAfterFee, tokenReserve);

        // Check against real liquidity
        uint256 realUSD = p.realReserveUSD();
        if (amountOut > realUSD) {
            amountOut = realUSD; // Cap at available real stables
        }
    }
}

contracts/v2/periphery/HLPMMRouterV2.sol.content:
// SPDX-License-Identifier: GPL-3.0
pragma solidity ^0.8.20;

import "../interfaces/IHLPMMRouterV2.sol";
import "../interfaces/IHLPMMFactoryV2.sol";
import "../interfaces/IHLPMMPoolV2.sol";
import "../interfaces/IStablecoinRegistry.sol";

interface IERC20Router {
    function balanceOf(address) external view returns (uint256);
    function transfer(address to, uint256 amount) external returns (bool);
    function transferFrom(address from, address to, uint256 amount) external returns (bool);
    function approve(address spender, uint256 amount) external returns (bool);
}

/// @title HLPMMRouterV2 - Smart multi-hop swap router
/// @notice Handles all swap routing:
///   - Stable → Token (single hop)
///   - Token → Stable (single hop)
///   - Token → Token (auto multi-hop via intermediate stable)
///   All stablecoins treated as fungible USD. User gets whatever stable the pool holds.
contract HLPMMRouterV2 is IHLPMMRouterV2 {
    error Expired();
    error InvalidPath();
    error PoolNotFound();
    error InsufficientOutput();
    error NotApprovedStablecoin();
    error ZeroAmount();

    address public immutable factory;
    address public immutable stablecoinRegistry;

    modifier ensure(uint256 deadline) {
        if (block.timestamp > deadline) revert Expired();
        _;
    }

    constructor(address factory_, address stablecoinRegistry_) {
        factory = factory_;
        stablecoinRegistry = stablecoinRegistry_;
    }

    // ─── Stable → Token ──────────────────────────────────────────────────

    /// @notice Swap stablecoins for tokens
    /// @param amountIn Amount of stablecoins to swap
    /// @param amountOutMin Minimum tokens to receive
    /// @param stablecoin The specific stablecoin being sent (must be approved)
    /// @param tokenOut The market token to buy
    /// @param to Recipient address
    /// @param deadline Transaction deadline
    function swapExactStableForTokens(
        uint256 amountIn,
        uint256 amountOutMin,
        address stablecoin,
        address tokenOut,
        address to,
        uint256 deadline
    ) external ensure(deadline) returns (uint256 amountOut) {
        if (amountIn == 0) revert ZeroAmount();
        if (!IStablecoinRegistry(stablecoinRegistry).isApprovedStablecoin(stablecoin)) {
            revert NotApprovedStablecoin();
        }

        address pool = IHLPMMFactoryV2(factory).tokenToPool(tokenOut);
        if (pool == address(0)) revert PoolNotFound();

        // Transfer stablecoins from user to pool
        IERC20Router(stablecoin).transferFrom(msg.sender, pool, amountIn);

        // Execute swap
        (amountOut, ) = IHLPMMPoolV2(pool).swap(
            stablecoin, stablecoin, amountIn, amountOutMin, to
        );

        if (amountOut < amountOutMin) revert InsufficientOutput();
    }

    // ─── Token → Stable ──────────────────────────────────────────────────

    /// @notice Swap tokens for stablecoins (user gets whatever stable pool holds)
    /// @param amountIn Amount of tokens to sell
    /// @param amountOutMin Minimum stablecoin amount to receive
    /// @param tokenIn The market token to sell
    /// @param to Recipient address
    /// @param deadline Transaction deadline
    function swapExactTokensForStable(
        uint256 amountIn,
        uint256 amountOutMin,
        address tokenIn,
        address to,
        uint256 deadline
    ) external ensure(deadline) returns (uint256 amountOut, address stablecoinOut) {
        if (amountIn == 0) revert ZeroAmount();

        address pool = IHLPMMFactoryV2(factory).tokenToPool(tokenIn);
        if (pool == address(0)) revert PoolNotFound();

        // Transfer tokens from user to pool
        IERC20Router(tokenIn).transferFrom(msg.sender, pool, amountIn);

        // Use first available stablecoin as the "preferred" output
        address[] memory stables = IStablecoinRegistry(stablecoinRegistry).getApprovedStablecoins();
        address preferredStable = stables[0];

        // Execute swap — pool will send whatever stablecoins it has
        (amountOut, stablecoinOut) = IHLPMMPoolV2(pool).swap(
            preferredStable, tokenIn, amountIn, amountOutMin, to
        );

        if (amountOut < amountOutMin) revert InsufficientOutput();
    }

    // ─── Token ↔ Token (smart multi-hop) ─────────────────────────────────

    /// @notice Swap any token for any other token via automatic USD intermediary
    /// @dev Handles: Token→Token (auto-hop), Stable→Token, Token→Stable
    /// @param amountIn Input amount
    /// @param amountOutMin Minimum output
    /// @param tokenIn Input token address
    /// @param tokenOut Output token address
    /// @param to Recipient
    /// @param deadline Transaction deadline
    function swapExactTokensForTokens(
        uint256 amountIn,
        uint256 amountOutMin,
        address tokenIn,
        address tokenOut,
        address to,
        uint256 deadline
    ) external ensure(deadline) returns (uint256 amountOut) {
        if (amountIn == 0) revert ZeroAmount();

        bool tokenInIsStable = IStablecoinRegistry(stablecoinRegistry).isApprovedStablecoin(tokenIn);
        bool tokenOutIsStable = IStablecoinRegistry(stablecoinRegistry).isApprovedStablecoin(tokenOut);

        if (tokenInIsStable && !tokenOutIsStable) {
            // Stable → Token
            address pool = IHLPMMFactoryV2(factory).tokenToPool(tokenOut);
            if (pool == address(0)) revert PoolNotFound();

            IERC20Router(tokenIn).transferFrom(msg.sender, pool, amountIn);
            (amountOut, ) = IHLPMMPoolV2(pool).swap(
                tokenIn, tokenIn, amountIn, amountOutMin, to
            );
        } else if (!tokenInIsStable && tokenOutIsStable) {
            // Token → Stable
            address pool = IHLPMMFactoryV2(factory).tokenToPool(tokenIn);
            if (pool == address(0)) revert PoolNotFound();

            IERC20Router(tokenIn).transferFrom(msg.sender, pool, amountIn);
            (amountOut, ) = IHLPMMPoolV2(pool).swap(
                tokenOutIsStable ? tokenOut : _getPreferredStable(),
                tokenIn, amountIn, 0, to // min check at end
            );
        } else if (!tokenInIsStable && !tokenOutIsStable) {
            // Token → Token (multi-hop: TokenA → Stable → TokenB)
            amountOut = _multiHopSwap(tokenIn, tokenOut, amountIn, to);
        } else {
            // Stable → Stable: just transfer (they're all 1:1 at protocol level)
            IERC20Router(tokenIn).transferFrom(msg.sender, to, amountIn);
            amountOut = amountIn;
        }

        if (amountOut < amountOutMin) revert InsufficientOutput();
    }

    /// @notice Multi-hop swap with explicit path
    /// @param amountIn Input amount
    /// @param amountOutMin Minimum final output
    /// @param path Array of token addresses defining the swap route
    /// @param to Recipient
    /// @param deadline Transaction deadline
    function swapExactTokensForTokensMultiHop(
        uint256 amountIn,
        uint256 amountOutMin,
        address[] calldata path,
        address to,
        uint256 deadline
    ) external ensure(deadline) returns (uint256 amountOut) {
        if (path.length < 2) revert InvalidPath();
        if (amountIn == 0) revert ZeroAmount();

        amountOut = amountIn;

        for (uint256 i = 0; i < path.length - 1; i++) {
            address currentIn = path[i];
            address currentOut = path[i + 1];
            bool isLast = (i == path.length - 2);
            address recipient = isLast ? to : address(this);

            bool inIsStable = IStablecoinRegistry(stablecoinRegistry).isApprovedStablecoin(currentIn);
            bool outIsStable = IStablecoinRegistry(stablecoinRegistry).isApprovedStablecoin(currentOut);

            if (inIsStable && !outIsStable) {
                // Stable → Token
                address pool = IHLPMMFactoryV2(factory).tokenToPool(currentOut);
                if (pool == address(0)) revert PoolNotFound();

                _safeTransfer(currentIn, pool, amountOut);
                (amountOut, ) = IHLPMMPoolV2(pool).swap(
                    currentIn, currentIn, amountOut, 0, recipient
                );
            } else if (!inIsStable && outIsStable) {
                // Token → Stable
                address pool = IHLPMMFactoryV2(factory).tokenToPool(currentIn);
                if (pool == address(0)) revert PoolNotFound();

                _safeTransfer(currentIn, pool, amountOut);
                (amountOut, ) = IHLPMMPoolV2(pool).swap(
                    currentOut, currentIn, amountOut, 0, recipient
                );
            } else if (!inIsStable && !outIsStable) {
                // Token → Token (auto-insert stable intermediate)
                amountOut = _multiHopSwap(currentIn, currentOut, amountOut, recipient);
            } else {
                // Stable → Stable (1:1)
                if (recipient != address(this)) {
                    _safeTransfer(currentIn, recipient, amountOut);
                }
            }
        }

        if (amountOut < amountOutMin) revert InsufficientOutput();
    }

    // ─── Internal ────────────────────────────────────────────────────────

    /// @notice Execute TokenA → Stable → TokenB multi-hop
    function _multiHopSwap(
        address tokenIn,
        address tokenOut,
        uint256 amountIn,
        address to
    ) internal returns (uint256 amountOut) {
        address poolIn = IHLPMMFactoryV2(factory).tokenToPool(tokenIn);
        address poolOut = IHLPMMFactoryV2(factory).tokenToPool(tokenOut);
        if (poolIn == address(0) || poolOut == address(0)) revert PoolNotFound();

        address preferredStable = _getPreferredStable();

        // Leg 1: TokenA → Stable (router receives stable)
        _safeTransfer(tokenIn, poolIn, amountIn);
        (uint256 stableAmount, address stableReceived) = IHLPMMPoolV2(poolIn).swap(
            preferredStable, tokenIn, amountIn, 0, address(this)
        );

        // Leg 2: Stable → TokenB (send to final recipient)
        _safeTransfer(stableReceived, poolOut, stableAmount);
        (amountOut, ) = IHLPMMPoolV2(poolOut).swap(
            stableReceived, stableReceived, stableAmount, 0, to
        );
    }

    function _getPreferredStable() internal view returns (address) {
        address[] memory stables = IStablecoinRegistry(stablecoinRegistry).getApprovedStablecoins();
        return stables[0];
    }

    function _safeTransfer(address tokenAddr, address to, uint256 amount) internal {
        (bool success, bytes memory data) = tokenAddr.call(
            abi.encodeWithSelector(IERC20Router.transfer.selector, to, amount)
        );
        require(success && (data.length == 0 || abi.decode(data, (bool))), "TRANSFER_FAILED");
    }
}

